INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('second-largest', 9, NULL, 'def gen():
    _s = [1744549851]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    SAME = 0
    V = 1000000000
    N = 200000
    n = N
    if SAME:
        a = [r(-1000, 1000)] * n
    else:
        a = [r(-V, V) for _ in range(n)]
    return f"{n}\n{'' ''.join(map(str, a))}\n"
', '999981415', 0);
